/// Module documentation🙂.
@ModuleInfo { minPklVersion = "0.32.0" }
open module stage103.declarations
import "pkl:reflect"
/// Alias documentation.
typealias Names<T> = Mapping<String,T>
/// Class documentation.
open class Parent {
  /// Name documentation.
  name: String = "base"
  hidden secret: Int = 2
  fixed fixedValue: Boolean = true
  const constValue: Int = 1
  function count(x: Int,y): Int = throw("method body must stay lazy")
}
class Child extends Parent {
  name = "child"
  own: List<String> = List("one")
  function extra(): String = "extra"
}
hidden field: Int = throw("field must stay lazy")
local localField = 3
function top(a: String,b): Boolean = true
hidden reflected = reflect.Module(module)
hidden cls = reflect.Class(Child)

module stage103.annotations
import "pkl:reflect"
class Mark extends Annotation { text: String }
@Mark { text = "parent" }
open class Parent {
  @Mark { text = "old" }
  hidden value: String = trace("default-parent")
}
@Mark { text = "child" }
class Child extends Parent {
  @Mark { text = "new" }
  value = trace("default-child")
}
abstract class Abstract {
  abstract absent: String
  uninitialized: Int
  implicit: Listing<Int>
}
hidden cls = reflect.Class(Child)

module stage103.locations
import "pkl:reflect"
/// First line.
// separator
/// Second line🙂.
class Named {
  /// Property line.
  // kept separator
  /// Next line.
  property: String = "x"
}
/// Alias line.
typealias Unicode = "🙂" | "x"

module stage103.referenceOrigin
import "pkl:ref"
class Domain extends ref.Domain { function renderReference(value: ref.Reference<Domain,Any>): String = throw("render must not be reached") }
hidden domain: Domain = new {}
name: String = "x"
hidden output: ModuleOutput = new { text = "override" }
